// Reactivos tipo examen — Parte 2 (Arts. 7 a 28 LIEPS y RLIEPS)
// Mismo estilo que la parte 1. Mantener el orden: el progreso se guarda por posición.
DB.quiz.push(
// ---- Enajenación ----
{ t:"ena", art:"Art. 7 LIEPS y art. 5 RLIEPS",
  q:"Durante una revisión, la autoridad detecta un faltante de bebidas alcohólicas en los inventarios de un fabricante. La empresa presenta actas y documentación para demostrar que los bienes se destruyeron con motivo de un siniestro ajeno a su voluntad y que no existió una venta. No se expidieron comprobantes por dichas mercancías. ¿Cómo debe analizarse el faltante?",
  o:["Como una enajenación definitiva, porque los faltantes de inventario no admiten justificación documental ni prueba en contrario del contribuyente.",
     "Como una presunción de enajenación que puede desvirtuarse mediante prueba en contrario, como la del caso fortuito.",
     "Como una operación ajena al IEPS, porque no se identificó a un adquirente de los bienes.",
     "Como una enajenación únicamente si la empresa expidió comprobantes por las mercancías."],
  a:1, why:"El faltante de bienes en inventarios se considera enajenación; la presunción admite prueba en contrario. El RLIEPS señala que no se consideran faltantes los originados por caso fortuito, fuerza mayor o destrucción autorizada y deducible para ISR.",
  hint:"Es una presunción, no una regla absoluta." },

{ t:"ena", art:"Art. 7, párr. 2 LIEPS",
  q:"Un productor retira de su almacén botellas de whisky de 750 mililitros que no destinará a su comercialización, sino a un evento interno con sus empleados. No existe contraprestación alguna ni se expide comprobante por la salida de los bienes. ¿Qué tratamiento corresponde al retiro?",
  o:["No causa el impuesto, porque no existe una venta ni una contraprestación cobrada.",
     "Se considera enajenación y se paga a más tardar el día 17 del mes siguiente, con el precio promedio de enajenación de los tres meses anteriores.",
     "Se considera una donación exenta, porque los bienes no salen del patrimonio del contribuyente.",
     "Se paga al cierre del ejercicio, tomando como valor el costo de producción de las bebidas, porque no existe precio pactado con un tercero."],
  a:1, why:"El retiro de bebidas del inciso A) del lugar de producción o del almacén, cuando no se destinen a comercialización y estén en envases de hasta 5,000 ml, se considera enajenación. Valor: precio promedio de enajenación de los tres meses inmediatos anteriores.",
  hint:"Retiro sin comercializar = enajenación." },

{ t:"ena", art:"Art. 7, último párrafo LIEPS",
  q:"Un bar vende al público en general bebidas alcohólicas en botellas abiertas y por copeo, para su consumo dentro del mismo establecimiento. El bar adquirió las botellas a un distribuidor que le cobró el precio con el impuesto incluido. Para efectos exclusivamente del IEPS, ¿cómo se analiza la venta que realiza el bar?",
  o:["Como enajenación gravada al 53%, porque se aplica la tasa sobre el precio de cada copa.",
     "No se considera enajenación, porque así lo dispone la Ley para la venta por copeo o en botella abierta para consumo en el mismo lugar.",
     "Como enajenación gravada únicamente si el bar es fabricante de las bebidas.",
     "Como enajenación gravada a la tasa del 0%, porque el impuesto ya se pagó en etapas anteriores y no puede trasladarse nuevamente al consumidor final."],
  a:1, why:"No se considera enajenación la venta de bebidas alcohólicas al público en general en botellas abiertas o por copeo, para consumo en el mismo establecimiento.",
  hint:"El IEPS ya se pagó en la cadena anterior." },

{ t:"ena", art:"Art. 7 LIEPS",
  q:"Una sociedad mercantil dona mercancías de su inventario cuya enajenación está gravada con el impuesto especial. Se establece expresamente que el donativo no es deducible para efectos del ISR y que la sociedad donataria no está autorizada para recibir donativos deducibles. ¿Cómo se clasifica la transmisión para efectos de la LIEPS?",
  o:["Como una transmisión excluida de enajenación, porque no existe una contraprestación.",
     "Como una enajenación, porque sólo se excluye la donación que sea deducible para los fines del ISR.",
     "Como una transmisión exenta, porque su finalidad no consiste en obtener utilidades y la donataria no realizará actividades gravadas.",
     "Como una transmisión fuera del objeto, porque no genera ingresos acumulables ni contraprestaciones efectivamente cobradas."],
  a:1, why:"No se considera enajenación la transmisión por causa de muerte o donación, siempre que la donación sea deducible para el ISR. Si no es deducible, sí es enajenación; se valúa a valor de mercado o avalúo.",
  hint:"La condición está ligada al ISR." },

{ t:"ena", art:"Art. 7, párr. 4 LIEPS",
  q:"Una empresa productora de diésel utiliza parte de su producción para abastecer los vehículos de su propia flotilla de reparto. No existe contraprestación ni se expide comprobante por esos consumos, y los vehículos se encuentran en territorio nacional. ¿Qué tratamiento corresponde a ese autoconsumo?",
  o:["No causa el impuesto, porque no existe una venta a un tercero.",
     "Se considera enajenación, porque la Ley así lo establece para el autoconsumo de los bienes de los incisos D) y H).",
     "Únicamente causa el impuesto al valor agregado por autoconsumo, porque el impuesto especial sólo grava las enajenaciones realizadas a terceros.",
     "Es un gasto deducible que no se encuentra gravado con el impuesto especial."],
  a:1, why:"También se considera enajenación el autoconsumo de bienes que realicen los contribuyentes del impuesto de los incisos D) y H) de la fr. I del art. 2.",
  hint:"Combustibles automotrices y fósiles." },

{ t:"ena", art:"Art. 8, fr. I, inc. c) LIEPS",
  q:"Una estación de servicio que no es fabricante, productora ni importadora enajena gasolina al público en general. Su proveedor es un importador que ya causó las cuotas correspondientes. La estación pregunta si debe calcular el impuesto sobre sus ventas. ¿Qué tratamiento corresponde?",
  o:["Debe pagar el impuesto únicamente sobre su margen de comercialización.",
     "No paga el impuesto y no se considera contribuyente por esas enajenaciones.",
     "Debe pagar el impuesto a la tasa del 16% sobre el precio al público.",
     "Debe pagar el impuesto y acreditar el que le trasladó su proveedor, porque es contribuyente por la enajenación de combustibles."],
  a:1, why:"No se paga el impuesto por enajenaciones de bienes de los incisos C), D), G) y H) y del art. 2o.-A realizadas por personas distintas de fabricantes, productores o importadores; no se consideran contribuyentes.",
  hint:"El impuesto se cobra en una sola etapa." },

{ t:"ena", art:"Art. 8, fr. I, inc. d) LIEPS",
  q:"Una tienda de abarrotes que no es fabricante, productora, envasadora, distribuidora ni importadora vende cerveza y cigarros al público en general. Expide comprobantes que no reúnen los requisitos del artículo 29-A del CFF y la mayor parte de sus ingresos proviene de consumidores finales. ¿Qué tratamiento corresponde a esas ventas?",
  o:["Debe pagar el impuesto, porque es quien realiza la enajenación al consumidor final.",
     "No paga el impuesto, porque se trata de enajenaciones al público en general realizadas por quien no es fabricante ni distribuidor.",
     "Únicamente paga el impuesto por la cerveza, porque los cigarros ya lo pagaron en su producción y no lo causan en las enajenaciones subsecuentes.",
     "Paga la mitad de la tasa, porque se trata de un comercio al menudeo."],
  a:1, why:"No se paga IEPS por enajenaciones de cerveza, bebidas refrescantes, cigarros, tabacos, productos con nicotina y energetizantes al público en general, salvo que el enajenante sea fabricante, productor, envasador, distribuidor o importador.",
  hint:"Si emitiera CFDI con requisitos del 29-A ya no sería \"público en general\"." },

{ t:"ena", art:"Art. 8, fr. I, inc. d) LIEPS",
  q:"Un comerciante de cerveza, que no es fabricante ni importador, obtiene la mayor parte de sus ingresos de ventas a restaurantes, a los que expide comprobantes con todos los requisitos fiscales. El resto de sus ventas las realiza a consumidores finales en mostrador. ¿Le es aplicable el beneficio de las enajenaciones al público en general?",
  o:["Sí, porque es comerciante y no fabricante, productor ni importador del bien, por lo que todas sus ventas se consideran realizadas al público en general.",
     "No, porque no gozan del beneficio quienes obtengan la mayor parte de sus ingresos de enajenaciones a quienes no son público en general.",
     "Sí, siempre que los restaurantes revendan la cerveza a sus comensales.",
     "Únicamente por las ventas que se paguen en efectivo."],
  a:1, why:"No gozan del beneficio los comerciantes que obtengan la mayor parte de sus ingresos de enajenaciones a personas que no son público en general; tampoco se considera público en general cuando se expiden comprobantes con requisitos del art. 29-A CFF.",
  hint:"Importa a quién le vende la mayor parte." },

{ t:"ena", art:"Art. 8, fr. I, inc. f) LIEPS",
  q:"Un restaurante vende a sus comensales refrescos con azúcares añadidos, servidos en vaso para su consumo con los alimentos. El restaurante no es fabricante ni importador de dichas bebidas y las adquiere de un distribuidor. ¿Paga el impuesto por esas ventas?",
  o:["Sí, a razón de $3.0818 por litro de bebida enajenada.",
     "No, porque no se paga el impuesto por la enajenación de bebidas saborizadas en restaurantes y lugares donde se proporcionan alimentos y bebidas.",
     "Sí, a la tasa del 8%, por tratarse de alimentos preparados que se consumen en el establecimiento junto con las bebidas saborizadas.",
     "Únicamente si las bebidas se sirven en envase cerrado."],
  a:1, why:"No se paga IEPS por bebidas saborizadas en restaurantes, bares y otros lugares de alimentos y bebidas; tampoco por las que tengan registro sanitario como medicamento, la leche y los sueros orales que cumplan la definición.",
  hint:"Exención por el lugar donde se vende." },

{ t:"ena", art:"Art. 8, fr. I, inc. e) LIEPS",
  q:"Una empresa enajena alcohol desnaturalizado a una industria química y cumple con las obligaciones del artículo 19 a las que la Ley condiciona el beneficio, entre ellas las de registro, información y control. No se trata de una exportación. ¿Qué tratamiento corresponde a la enajenación?",
  o:["Causa el impuesto a la tasa del 50%, porque se trata de alcohol desnaturalizado y la exención sólo procede en la exportación.",
     "No paga el impuesto, porque cumple las obligaciones del artículo 19 a las que la Ley condiciona la exención.",
     "Causa el impuesto a la tasa del 26.5%, porque no es una bebida lista para su consumo.",
     "Causa el impuesto únicamente si se enajena a granel."],
  a:1, why:"El alcohol, alcohol desnaturalizado y mieles incristalizables no pagan IEPS en su enajenación siempre que se cumplan las obligaciones del art. 19 que la propia fracción señala.",
  hint:"Exención condicionada a cumplir obligaciones." },

{ t:"ena", art:"Art. 8, fr. II y art. 19, fr. XI LIEPS",
  q:"Una tequilera exporta en definitiva tequila envasado a un importador residente en el extranjero. La exportación se realiza conforme a la legislación aduanera, y el producto no corresponde a alimentos no básicos del inciso J). ¿Qué tratamiento corresponde y qué requisito debe cumplir el exportador?",
  o:["Se grava a la tasa del 0%, sin requisito adicional, porque se trata de una exportación definitiva realizada conforme a la legislación aduanera.",
     "No se paga el impuesto por la exportación, y el exportador debe estar inscrito en el padrón de exportadores sectorial.",
     "Causa el 53% y el exportador debe solicitar después la devolución del impuesto.",
     "No es objeto del impuesto, porque el consumo se realiza en el extranjero."],
  a:1, why:"No se paga IEPS por la exportación de los bienes de la Ley (salvo la tasa 0% del art. 2, fr. III para alimentos no básicos). Los exportadores de bienes de los incisos A), B), C), D), F), G), H) e I) deben estar inscritos en el padrón sectorial.",
  hint:"Distingue exportación exenta (art. 8) de tasa 0% (art. 2, fr. III)." },

{ t:"ena", art:"Art. 8, fr. III LIEPS",
  q:"Una tienda departamental organiza un sorteo en el que sus clientes obtienen el derecho a participar, a título gratuito, por la adquisición de un bien. En el año obtiene 8 permisos y el valor de los premios equivale al 2% de los ingresos que obtuvo en el año inmediato anterior. ¿Qué tratamiento corresponde?",
  o:["Causa el 50% sobre el valor de los comprobantes que dieron derecho a participar, porque el sorteo requiere permiso de la autoridad competente.",
     "No paga el impuesto, porque no obtiene más de diez permisos y los premios no exceden del 3% de sus ingresos del año anterior.",
     "Causa el impuesto únicamente sobre el valor de los premios entregados.",
     "No paga el impuesto sólo si es donataria autorizada."],
  a:1, why:"No se paga IEPS en sorteos en que los participantes obtienen la calidad a título gratuito por adquirir un bien, si el realizador no obtiene más de 10 permisos al año y los premios no exceden el 3% de los ingresos del año anterior.",
  hint:"Dos números: 10 permisos y 3%." },

{ t:"ena", art:"Art. 8, fr. IV, inc. d) LIEPS",
  q:"Una empresa de telecomunicaciones comercializa un paquete que incluye televisión de paga, telefonía y acceso a internet por un solo precio mensual. Al emitir el comprobante, separa la contraprestación que corresponde al acceso a internet. ¿Bajo qué condiciones procede la exención de ese concepto?",
  o:["Todo el paquete está exento, porque incluye un servicio de acceso a internet y la Ley no permite fraccionar la contraprestación de un mismo servicio.",
     "Procede si el internet se separa a valor de mercado, sin que lo exento exceda del 30% del total facturado en conjunto.",
     "No procede la exención cuando el servicio se ofrece en paquete.",
     "Procede hasta por el 50% del precio total del paquete."],
  a:1, why:"El acceso a internet está exento; si se ofrece en paquete, el comprobante debe separar su contraprestación (a valor como si se cobrara por separado) y lo exento no puede exceder del 30% del total facturado en conjunto.",
  hint:"Límite: 30%." },

{ t:"ena", art:"Art. 8, fr. IV LIEPS",
  q:"Una concesionaria presta diversos servicios a través de redes públicas de telecomunicaciones en distintas localidades del país. Para determinar el impuesto del mes, debe identificar cuáles de esos servicios no se encuentran gravados. ¿Cuál de los siguientes servicios está exento?",
  o:["La telefonía móvil prestada en ciudades con más de un millón de habitantes.",
     "La telefonía fija rural prestada en poblaciones de hasta 5,000 habitantes, conforme al último censo de población.",
     "La televisión de paga prestada en zonas rurales.",
     "La mensajería instantánea con cobro por suscripción."],
  a:1, why:"Están exentos: telefonía fija rural (poblaciones de hasta 5,000 habitantes), telefonía pública, interconexión y acceso a internet.",
  hint:"El dato está ligado al censo de población." },

{ t:"ena", art:"Art. 9 LIEPS",
  q:"Un productor residente en México vende cerveza a un cliente de Guatemala. El contrato se firmó en Guatemala, pero la cerveza se encontraba en Jalisco al iniciarse su envío al comprador. Para determinar exclusivamente la territorialidad de la enajenación, sin analizar su eventual tratamiento de exportación, ¿qué conclusión corresponde?",
  o:["La enajenación se efectúa en Guatemala, porque allí se celebró el contrato de compraventa.",
     "La enajenación se efectúa en territorio nacional, porque el bien se encontraba en México al efectuarse su envío al adquirente.",
     "La enajenación se efectúa en Guatemala, porque allí se encuentra el domicilio del comprador que recibe las mercancías.",
     "La enajenación se efectúa fuera de México, porque la entrega final de las mercancías al adquirente ocurre en otro país."],
  a:1, why:"La enajenación se efectúa en territorio nacional si en él se encuentra el bien al efectuarse el envío al adquirente o, sin envío, si se realiza en el país la entrega material.",
  hint:"Igual que la regla de territorialidad del IVA." },

{ t:"ena", art:"Art. 10 LIEPS",
  q:"Un fabricante enajena en noviembre bebidas alcohólicas por $100,000, sin impuestos. En ese mes cobra efectivamente $40,000, y el resto lo cobra en enero del año siguiente. No se trata de faltantes, autoconsumo ni donaciones. ¿Cuándo se causa el impuesto?",
  o:["Sobre el total en noviembre, porque en ese mes se celebró la enajenación y se transmitió la propiedad de los bienes.",
     "Sobre $40,000 en noviembre y sobre $60,000 en enero, conforme se cobran efectivamente.",
     "Sobre el total en enero, porque en ese mes se liquida la contraprestación.",
     "Sobre el total en la fecha de expedición del comprobante fiscal."],
  a:1, why:"En la enajenación, el IEPS se causa en el momento en que se cobren las contraprestaciones y sobre el monto de lo cobrado; si se cobran parcialmente, se aplica la tasa a la parte efectivamente percibida.",
  hint:"Flujo de efectivo." },

{ t:"ena", art:"Art. 10, párr. 2 y 3 LIEPS",
  q:"Un contribuyente detecta en junio, mediante un conteo interno, un faltante de bienes gravados en sus inventarios, pero no lo reporta. La autoridad lo descubre en agosto durante una visita domiciliaria. El contribuyente no aporta prueba que desvirtúe la presunción. ¿Cuándo se considera efectuada la enajenación?",
  o:["En agosto, porque en ese mes la autoridad descubrió el faltante y sólo entonces existe certeza jurídica sobre la enajenación.",
     "En junio, porque la enajenación se considera efectuada cuando el contribuyente o las autoridades conozcan el faltante, lo que ocurra primero.",
     "Al cierre del ejercicio, porque los faltantes se determinan anualmente.",
     "En la fecha del último inventario anterior al faltante."],
  a:1, why:"En faltantes, consumo o autoconsumo, la enajenación se efectúa cuando el contribuyente o las autoridades conozcan los hechos, lo que ocurra primero. En donaciones gravadas, al entregar el bien o extender el comprobante, lo primero.",
  hint:"\"Lo que ocurra primero\"." },

{ t:"ena", art:"Art. 11 LIEPS",
  q:"Un productor de cigarros enajena su producto a un mayorista, que a su vez lo vende a comercios detallistas, quienes finalmente lo venden al consumidor. Para calcular el impuesto ad valorem a cargo del productor, debe determinar el valor que sirve de base. ¿Qué valor corresponde?",
  o:["La contraprestación pactada con el mayorista, porque es el adquirente directo del productor.",
     "El precio de venta al detallista, porque así lo establece la Ley para los cigarros y otros productos que contengan nicotina.",
     "El precio sugerido de venta al público, porque el impuesto grava el consumo final.",
     "El costo de producción más la utilidad bruta del productor."],
  a:1, why:"Productores o importadores de cigarros y otros productos con nicotina consideran como valor el precio de venta al detallista; para puros y otros tabacos labrados, la contraprestación pactada.",
  hint:"El valor está un eslabón antes del consumidor." },

// ---- Importación ----
{ t:"imp", art:"Art. 12 LIEPS",
  q:"Una empresa introduce bebidas alcohólicas al país bajo el régimen de importación temporal y, meses después, decide cambiarlas al régimen de importación definitiva para comercializarlas en territorio nacional. Para efectos exclusivamente del momento de causación, ¿cuándo se causa el impuesto?",
  o:["Al ingresar las mercancías al país, porque en ese momento se presenta el primer pedimento.",
     "Al convertirse la importación temporal en definitiva.",
     "Al venderlas en territorio nacional, porque hasta ese momento se cobra la contraprestación.",
     "No se causa, porque la importación inició como temporal."],
  a:1, why:"En importación, el IEPS se causa: al presentar el pedimento; en importación temporal, al convertirse en definitiva; y en introducción ilegal, cuando se descubra o se embarguen las mercancías.",
  hint:"Son tres momentos de causación." },

{ t:"imp", art:"Art. 12, fr. III LIEPS",
  q:"La autoridad aduanera descubre y embarga en una bodega cigarros que fueron introducidos ilegalmente al país, sin que se haya presentado pedimento alguno. No es posible determinar con precisión la fecha en que se internaron las mercancías. ¿Cuándo se causa el impuesto?",
  o:["Nunca, porque no se presentó el pedimento de importación.",
     "Cuando la internación ilegal sea descubierta o las mercancías sean embargadas por las autoridades.",
     "En la fecha estimada de introducción de las mercancías, determinada con los elementos que obtenga la autoridad durante su revisión.",
     "Al rematarse las mercancías embargadas."],
  a:1, why:"En bienes introducidos ilegalmente, el impuesto se causa cuando la internación sea descubierta o las mercancías sean embargadas por las autoridades.",
  hint:"El momento en que la autoridad se entera." },

{ t:"imp", art:"Art. 13, fr. II LIEPS",
  q:"Un pasajero internacional ingresa al país con dos botellas de vino dentro de los límites de la franquicia que establece la legislación aduanera. Las botellas son para su consumo personal y no serán comercializadas. ¿Debe pagar el impuesto especial por esa importación?",
  o:["Sí, a la tasa del 26.5%, porque se trata de bebidas con contenido alcohólico y la franquicia sólo libera del pago de aranceles.",
     "No, porque no se paga el impuesto en las importaciones de pasajeros en los términos de la legislación aduanera.",
     "Sólo si posteriormente enajena las botellas en territorio nacional.",
     "Sí, pero puede acreditarlo en su declaración mensual."],
  a:1, why:"Están exentas las importaciones de pasajeros en términos de la legislación aduanera y las de misiones diplomáticas, con los controles que establezca la SHCP.",
  hint:"Exención por tipo de importador." },

{ t:"imp", art:"Art. 13, fr. I LIEPS",
  q:"Una maquiladora introduce bienes gravados bajo el régimen de importación temporal para elaboración, transformación o reparación, al amparo de un programa de maquila y exportación. Considera que, por tratarse de una importación temporal, no causa el impuesto. ¿Qué criterio corresponde?",
  o:["Es correcto, porque toda importación temporal se encuentra exenta.",
     "Es incorrecto, porque la exención de importaciones temporales no aplica a los programas de maquila o exportación y regímenes similares.",
     "Es correcto, siempre que los bienes retornen al extranjero dentro del plazo de un año, conforme al régimen de importación temporal.",
     "Es correcto, sólo si los bienes no son bebidas alcohólicas."],
  a:1, why:"Las importaciones temporales están exentas, salvo las destinadas a importación temporal para elaboración, transformación o reparación en programas de maquila o exportación, depósito fiscal automotriz, recinto fiscalizado y recinto fiscalizado estratégico.",
  hint:"Igual que en IVA: los regímenes IMMEX sí causan." },

{ t:"imp", art:"Art. 14 LIEPS",
  q:"Un importador introduce en definitiva bebidas alcohólicas. El valor en aduana es de $100,000, el impuesto general de importación de $20,000, el derecho de trámite aduanero de $800 y el IVA de importación de $19,000. No existen otras contribuciones ni aprovechamientos. Conforme a la Ley, ¿cuál es la base del impuesto especial?",
  o:["$100,000, al considerar únicamente el valor en aduana de las mercancías.",
     "$120,800, al sumar al valor en aduana el IGI y el derecho de trámite aduanero, sin incluir el IVA.",
     "$139,800, al sumar al valor en aduana todas las contribuciones causadas con motivo de la importación, incluido el IVA.",
     "$120,000, al sumar únicamente el impuesto general de importación al valor en aduana."],
  a:1, why:"La base es el valor para el IGI más las contribuciones y aprovechamientos por la importación, excepto el IVA: 100,000 + 20,000 + 800 = $120,800.",
  hint:"Todo suma, menos un impuesto." },

{ t:"imp", art:"Art. 15 LIEPS",
  q:"Un importador de bebidas alcohólicas pretende retirar sus mercancías del recinto aduanero y cubrir el impuesto especial hasta el día 17 del mes siguiente, junto con su declaración de enajenaciones. Las mercancías no se destinan a depósito fiscal. ¿Es procedente?",
  o:["Sí, porque el impuesto se calcula mensualmente y se paga a más tardar el día 17.",
     "No, porque en importación el impuesto se paga conjuntamente con el IGI y las mercancías no pueden retirarse de la aduana sin el pago previo.",
     "Sí, siempre que otorgue una garantía del interés fiscal que cubra el impuesto, su actualización y los recargos correspondientes.",
     "Sí, si es contribuyente habitual del impuesto."],
  a:1, why:"En importación el IEPS se paga junto con el IGI (aun cuando éste se difiera por depósito fiscal). Si no hay IGI, se paga mediante declaración en la aduana. No pueden retirarse mercancías sin el pago previo.",
  hint:"El pago se hace en la aduana." },

{ t:"imp", art:"Art. 15-A LIEPS",
  q:"Una empresa con programa de maquila y exportación obtuvo la certificación del SAT para aplicar un crédito fiscal en el impuesto que causa al introducir bienes bajo importación temporal. Consulta el alcance del beneficio y la vigencia de la certificación. ¿Qué establece la Ley?",
  o:["Una exención total del impuesto, con certificación por tiempo indefinido.",
     "Un crédito fiscal equivalente al 100% del impuesto, con certificación de un año renovable dentro de los 30 días anteriores a su vencimiento.",
     "Un crédito fiscal del 50% del impuesto, con certificación de dos años renovable a solicitud del contribuyente antes de su vencimiento.",
     "La devolución inmediata del impuesto, con certificación de seis meses."],
  a:1, why:"Crédito fiscal equivalente al 100% del IEPS. Certificación con vigencia de un año, renovable dentro de los 30 días anteriores al vencimiento. El impuesto cubierto con el crédito no es acreditable y el crédito no es ingreso acumulable para ISR.",
  hint:"100%, un año, 30 días." },

{ t:"imp", art:"Art. 15-A, último párrafo LIEPS",
  q:"Una empresa con programa de maquila y exportación decide no solicitar la certificación ante el SAT. Introducirá bienes gravados bajo importación temporal y desea evitar el desembolso del impuesto en ese momento. ¿Qué alternativa le otorga la Ley?",
  o:["Ninguna, porque sin certificación siempre debe pagarse el impuesto en la importación, conforme a las reglas generales del artículo 15.",
     "Puede no pagar el impuesto siempre que garantice el interés fiscal mediante fianza otorgada por institución autorizada.",
     "Puede no pagarlo sin requisito adicional, por tratarse de una importación temporal.",
     "Puede no pagarlo sólo si exporta al menos el 90% de su producción."],
  a:1, why:"Quienes no ejerzan la opción de certificarse pueden no pagar el IEPS, siempre que garanticen el interés fiscal mediante fianza otorgada por institución autorizada.",
  hint:"Una garantía sustituye al pago." },

{ t:"imp", art:"Art. 16 LIEPS",
  q:"Una persona física que no es contribuyente habitual del impuesto realiza ocasionalmente la importación de un bien gravado. No presenta declaraciones mensuales del IEPS ni tiene otras actividades gravadas. ¿Cómo debe pagar el impuesto?",
  o:["A más tardar el día 17 del mes siguiente a la importación, mediante la declaración mensual definitiva del impuesto.",
     "En los términos del artículo 15, es decir, conjuntamente con el impuesto general de importación.",
     "En la declaración anual del ejercicio en que se realizó la importación.",
     "No paga el impuesto, por tratarse de una importación ocasional."],
  a:1, why:"En la importación ocasional, el pago se hace en los términos del art. 15 de la Ley.",
  hint:"Remite al artículo anterior." },

// ---- Servicios ----
{ t:"ser", art:"Art. 17 LIEPS",
  q:"Una empresa presta servicios gravados a través de redes públicas de telecomunicaciones y pacta con su cliente el pago en parcialidades mensuales. El contrato se firmó en enero, pero las parcialidades se cobran efectivamente entre febrero y junio. ¿Cómo se determina el impuesto?",
  o:["Sobre el total contratado, en el mes en que se firmó el contrato, porque en ese momento nace la obligación de pago.",
     "Sobre cada parcialidad efectivamente cobrada, en el momento en que se cobra.",
     "Sobre el total, al concluir la prestación del servicio, porque hasta entonces se conoce la contraprestación definitiva.",
     "Sobre el total, en el mes en que se expide el comprobante global."],
  a:1, why:"En servicios, el valor es la contraprestación; el impuesto se causa cuando se cobran efectivamente y sobre el monto de cada una; si se cobran parcialmente, sobre la parte percibida. Se paga conforme al art. 5.",
  hint:"Igual que en enajenación: flujo de efectivo." },

{ t:"ser", art:"Art. 18 LIEPS",
  q:"Un casino capta en el mes $1,000,000 en apuestas, paga $700,000 en premios y devuelve $10,000 a los participantes antes de la celebración del evento, cantidades que quedan debidamente registradas. No se trata de juegos por internet de residentes en el extranjero. ¿Cuál es la base del impuesto?",
  o:["$1,000,000, al considerar el total de las apuestas captadas sin disminución alguna de premios ni devoluciones.",
     "$300,000, al disminuir únicamente los premios efectivamente pagados.",
     "$290,000, al disminuir los premios pagados y las cantidades devueltas antes del evento.",
     "$990,000, al disminuir únicamente las cantidades devueltas a los participantes."],
  a:2, why:"El valor es el monto total de las apuestas, que se puede disminuir con premios efectivamente pagados y cantidades devueltas antes del evento y registradas: 1,000,000 − 700,000 − 10,000 = $290,000.",
  hint:"Se restan dos conceptos." },

{ t:"ser", art:"Art. 18, último párrafo LIEPS",
  q:"Un residente en el extranjero sin establecimiento permanente en México ofrece, a través de internet, juegos con apuestas a usuarios ubicados en territorio nacional. En el mes paga premios a varios de ellos y pretende disminuirlos de la base. ¿Cómo debe determinar el valor sobre el que se calcula el impuesto?",
  o:["Disminuyendo de las apuestas los premios efectivamente pagados, porque ésa es la regla general que la Ley establece para los juegos con apuestas.",
     "Considerando el total de las cantidades efectivamente percibidas de los participantes, sin disminución alguna.",
     "Considerando únicamente la comisión que retiene por cada apuesta.",
     "No determina base, porque al residir en el extranjero no causa el impuesto."],
  a:1, why:"Para los juegos y sorteos por internet del segundo párrafo del inciso B), se considera como valor el total de lo efectivamente percibido de los participantes, sin disminución alguna.",
  hint:"La reforma 2026 no permite restar premios en este caso." },

{ t:"ser", art:"Art. 18, párr. 2 LIEPS",
  q:"Una empresa realiza un sorteo cuyo premio se encuentra de manera referenciada y oculta en algunos de los productos que vende, de modo que el derecho a participar se obtiene al adquirir cualquiera de ellos. Debe determinar la base del impuesto por la realización del sorteo. ¿Qué valor corresponde?",
  o:["El valor de los premios entregados a los ganadores, porque son lo único que se obtiene a través del sorteo.",
     "El precio en que se enajenaron todos los bienes que participan en el sorteo.",
     "El costo de producción de los productos que contenían premio.",
     "Ninguno, porque la participación es gratuita para el consumidor."],
  a:1, why:"Si el premio está contenido de manera referenciada y oculta en bienes cuya adquisición da derecho a participar, el valor es el precio en que se enajenaron todos los bienes que participan.",
  hint:"Todos los productos participantes." },

{ t:"ser", art:"Art. 18-A LIEPS",
  q:"Un servicio de telecomunicaciones se origina en Texas, Estados Unidos, y termina en Monterrey, Nuevo León. El prestador cobra la totalidad de la contraprestación a su cliente. Para efectos exclusivamente de la territorialidad, ¿se considera prestado en territorio nacional?",
  o:["No, porque el servicio se originó en el extranjero.",
     "Sí, porque se considera prestado en territorio nacional cuando se lleva a cabo en él, total o parcialmente.",
     "Sólo en un 50%, porque la mitad del trayecto del servicio ocurre en cada país y la contraprestación debe proporcionarse.",
     "Sólo si el prestador es residente en México."],
  a:1, why:"Se considera que los servicios de telecomunicaciones se prestan en territorio nacional cuando se llevan a cabo en él, total o parcialmente.",
  hint:"Basta una parte." },

{ t:"ser", art:"Art. 18-B LIEPS",
  q:"Un residente en el extranjero sin establecimiento en México vende descargas de videojuegos clasificados para adultos a usuarios que se encuentran en Colima. Sus servidores se ubican fuera del país y los pagos se realizan con tarjetas emitidas en el extranjero. ¿Se considera prestado el servicio en territorio nacional?",
  o:["No, porque los servidores del prestador se encuentran en el extranjero y desde ahí se presta materialmente el servicio.",
     "Sí, porque el receptor del servicio se encuentra en territorio nacional, conforme a la LIVA.",
     "Sólo si el pago se realiza con una tarjeta emitida en México.",
     "No, porque los servicios digitales no son objeto del impuesto especial."],
  a:1, why:"En servicios digitales de juegos por internet y videojuegos prestados por extranjeros sin establecimiento, el servicio se presta en territorio nacional cuando el receptor se encuentra en él (art. 18-C LIVA).",
  hint:"Importa dónde está quien recibe." },

// ---- Obligaciones ----
{ t:"obl", art:"Art. 19, fr. II LIEPS",
  q:"Un fabricante de cigarros enajena su producto a un mayorista que es contribuyente del impuesto. El mayorista le solicita que el impuesto aparezca en forma expresa y por separado en el comprobante fiscal. ¿Qué procede?",
  o:["Debe desglosarlo, porque el adquirente es contribuyente del impuesto y lo solicita expresamente para efectos de su acreditamiento.",
     "No debe trasladarlo en forma expresa y por separado, porque los cigarros no están entre los bienes que lo permiten.",
     "Debe desglosarlo únicamente si el mayorista es también importador.",
     "Debe expedir dos comprobantes, uno por el bien y otro por el impuesto."],
  a:1, why:"Los comprobantes se expiden sin traslado expreso y por separado, salvo bienes de los incisos A), D), F), G), I) y J) cuando el adquirente sea contribuyente del impuesto por esos bienes y lo solicite.",
  hint:"La lista de incisos no incluye C." },

{ t:"obl", art:"Art. 19, fr. III LIEPS",
  q:"Una sociedad tiene tres establecimientos en distintas entidades federativas. Todos pertenecen al mismo contribuyente y las operaciones no se ubican en las excepciones que establece la Ley. ¿Cómo debe presentar sus declaraciones de pago del impuesto?",
  o:["Una declaración por entidad federativa, agrupando los establecimientos ubicados en cada estado.",
     "Una sola declaración por todos los establecimientos, ante las oficinas autorizadas que correspondan a su domicilio fiscal.",
     "Una declaración por establecimiento, determinada conforme al lugar donde se realizan las operaciones.",
     "Una sola declaración por el establecimiento que genere el mayor importe de actividades gravadas en el periodo."],
  a:1, why:"Si un contribuyente tiene varios establecimientos, presentará por todos ellos una sola declaración de pago ante las oficinas autorizadas correspondientes a su domicilio fiscal.",
  hint:"Una sola declaración." },

{ t:"obl", art:"Art. 19, fr. IV LIEPS",
  q:"Un importador de cigarros registró su lista de precios con la declaración del primer mes del ejercicio. En julio modifica los precios de venta al detallista de varias de sus marcas. ¿Qué plazo tiene para informar la modificación?",
  o:["A más tardar el día 17 del mes siguiente, junto con su pago mensual.",
     "Dentro de los 5 días siguientes a la fecha en que se realice la modificación de precios.",
     "En la declaración del primer mes del ejercicio siguiente.",
     "Dentro de los 15 días siguientes a la modificación."],
  a:1, why:"Productores e importadores de cigarros registran su lista de precios con la declaración del primer mes del año y deben informar cualquier modificación dentro de los 5 días siguientes.",
  hint:"Plazo muy corto." },

{ t:"obl", art:"Art. 19, fr. V LIEPS",
  q:"Un productor de bebidas alcohólicas envasa su producto en botellas de 750 mililitros que almacenará durante varias semanas antes de su venta. Consulta en qué momento debe adherir los marbetes a los envases. ¿Qué establece la Ley?",
  o:["Antes de su enajenación, una vez que se identifique al adquirente.",
     "Inmediatamente después de su envasamiento, con independencia del tiempo que permanezcan almacenadas.",
     "Al trasladar las botellas al almacén de producto terminado.",
     "Cuando el cliente solicite el comprobante fiscal."],
  a:1, why:"Los marbetes se adhieren inmediatamente después del envasamiento. A granel se adhieren precintos cuando estén en tránsito o transporte. Los importadores los colocan antes de la internación o en la aduana, almacén o recinto autorizado.",
  hint:"Justo después de llenar la botella." },

{ t:"obl", art:"Art. 19, fr. VI LIEPS",
  q:"Un contribuyente enajenó durante el año bienes gravados que fueron entregados materialmente en varias entidades federativas, según consta en sus comprobantes fiscales. Debe informar a la autoridad el consumo por entidad federativa del año anterior. ¿En qué mes debe hacerlo?",
  o:["Durante enero, junto con la declaración del primer mes del ejercicio.",
     "Durante marzo de cada año.",
     "Durante abril, junto con la información trimestral de clientes y proveedores.",
     "Durante julio, junto con la información semestral."],
  a:1, why:"Se proporciona durante marzo de cada año. Los bienes se consideran consumidos donde se hace la entrega material, según el comprobante fiscal.",
  hint:"Coincide con el mes de la anual de personas morales." },

{ t:"obl", art:"Art. 19, fr. VIII LIEPS",
  q:"Un contribuyente que enajena bebidas alcohólicas distintas de los vinos de mesa debe proporcionar información sobre sus 50 principales clientes y proveedores. No realiza importaciones ni exportaciones. ¿Con qué periodicidad debe presentarla?",
  o:["Mensualmente, junto con su declaración de pago.",
     "Trimestralmente, en abril, julio, octubre y enero, respecto del trimestre anterior.",
     "Semestralmente, en enero y julio, respecto del semestre anterior, como ocurre con todas las bebidas alcohólicas.",
     "Anualmente, durante marzo del año siguiente."],
  a:1, why:"Es trimestral (abril, julio, octubre y enero) respecto del trimestre anterior. Quienes enajenen o importen vinos de mesa lo hacen semestralmente, en enero y julio.",
  hint:"Los vinos de mesa tienen un régimen especial." },

{ t:"obl", art:"Art. 19, fr. XII LIEPS",
  q:"Un destilador de alcohol iniciará un nuevo proceso de destilación en su planta, para el cual cuenta con existencias de materia prima. Consulta con cuánta anticipación debe reportar la fecha de inicio a la autoridad. ¿Qué plazo establece la Ley?",
  o:["Con 5 días de anticipación.",
     "Con 15 días de anticipación.",
     "Con 30 días de anticipación.",
     "No debe reportarlo, porque basta con registrarlo en su contabilidad."],
  a:1, why:"Debe reportar la fecha de inicio con quince días de anticipación (con existencias) y la conclusión dentro de los quince días siguientes. En enero reporta las características de sus equipos. Equipos nuevos, modificados o enajenados: aviso dentro de 15 días.",
  hint:"El mismo número aparece tres veces en la fracción." },

{ t:"obl", art:"Art. 19, fr. XVIII LIEPS",
  q:"Un bar agota el contenido de una botella de tequila que vendió por copeo a sus clientes para su consumo en el mismo lugar. No ha optado por algún esquema alternativo previsto en reglas de carácter general. ¿Qué debe hacer con el envase vacío?",
  o:["Devolverlo al proveedor para su reutilización.",
     "Destruirlo inmediatamente después de que se agote su contenido.",
     "Conservarlo durante un año como parte de su contabilidad, para acreditar el origen lícito de las bebidas vendidas.",
     "Rellenarlo con producto adquirido a granel."],
  a:1, why:"Quienes enajenen al público bebidas para consumo en el mismo lugar deben destruir los envases inmediatamente después de agotar su contenido (salvo los casos que el SAT establezca por reglas).",
  hint:"Se busca evitar el rellenado." },

{ t:"obl", art:"Arts. 19, fr. XXII y 19-A LIEPS",
  q:"En una verificación realizada a un puesto semifijo en la vía pública, la autoridad encuentra cajetillas de cigarros que no tienen impreso el código de seguridad. El vendedor manifiesta que las adquirió a un tercero que no identifica. ¿Qué procede respecto de las cajetillas?",
  o:["Se impone una multa al vendedor y se le devuelve la mercancía.",
     "Se aseguran y pasan a propiedad del fisco federal para su destrucción, aun cuando se encuentren en un puesto semifijo.",
     "Se cobra el impuesto omitido y se liberan las cajetillas.",
     "No procede medida alguna, porque el código sólo es obligatorio para los puros."],
  a:1, why:"Las cajetillas sin código de seguridad se aseguran y pasan a propiedad del fisco federal para su destrucción. El SAT puede verificar en cualquier local, incluso puestos fijos o semifijos (art. 49 CFF).",
  hint:"Aseguramiento + destrucción." },

{ t:"obl", art:"Art. 19, fr. XXII LIEPS",
  q:"La obligación de imprimir un código de seguridad en cada una de las cajetillas o empaques corresponde a productores, fabricantes e importadores de tabacos labrados. Sin embargo, la Ley establece una excepción para cierto tipo de productos. ¿Quiénes no están obligados a imprimirlo?",
  o:["Los importadores de cigarros con filtro.",
     "Los productores de puros y otros tabacos labrados hechos enteramente a mano.",
     "Los fabricantes de cigarros que venden exclusivamente a mayoristas y no al público en general.",
     "Los productores de tabaco picado para uso industrial."],
  a:1, why:"La obligación aplica a productores, fabricantes e importadores de cigarros y otros tabacos labrados, con excepción de puros y otros tabacos labrados hechos enteramente a mano.",
  hint:"Los artesanales vuelven a ser excepción." },

{ t:"obl", art:"Art. 20 LIEPS",
  q:"Un casino incumple la obligación de proporcionar al SAT, en línea y en tiempo real, la información de su sistema central de apuestas. La falla se debe a una decisión de la propia empresa y no a causas ajenas, y no se dio aviso a la autoridad. ¿Qué sanción prevé la LIEPS?",
  o:["Únicamente una multa conforme al Código Fiscal de la Federación, por tratarse de una obligación formal de información.",
     "La clausura del establecimiento o establecimientos donde realice los juegos con apuestas.",
     "La cancelación de su inscripción en el RFC.",
     "La pérdida del derecho a disminuir los premios pagados."],
  a:1, why:"El incumplimiento del art. 20 se sanciona con la clausura, salvo fallas no imputables con aviso al SAT. La clausura se levanta al subsanar la infracción y requiere visita domiciliaria (arts. 42 fr. V y 49 CFF).",
  hint:"Sanción más grave que una multa." },

{ t:"obl", art:"Art. 21 LIEPS",
  q:"Un contribuyente que enajena combustibles automotrices del inciso D) debe informar a la autoridad los volúmenes enajenados y autoconsumidos durante el primer semestre del año. ¿Cuál es la fecha límite para presentar esa declaración?",
  o:["El 17 de julio, junto con el pago del mes de junio.",
     "El 20 de septiembre del mismo año.",
     "El 20 de marzo del año siguiente.",
     "El 31 de diciembre del mismo año."],
  a:1, why:"Declaración semestral: primer semestre a más tardar el 20 de septiembre; segundo semestre el 20 de marzo del año siguiente.",
  hint:"Día 20, pero no del mes siguiente." },

// ---- Facultades ----
{ t:"fac", art:"Art. 22 LIEPS y art. 19 RLIEPS",
  q:"La autoridad determina presuntivamente un valor de $500,000, sin impuestos, correspondiente exclusivamente a la enajenación de bebidas de 40° G.L. El contribuyente comprueba $30,000 de impuesto acreditable de esos meses. No hay retenciones, pagos previos ni otros conceptos que deban disminuirse. ¿Cuál es el impuesto resultante?",
  o:["$265,000, al aplicar la tasa al valor presunto sin admitir reducciones por acreditamiento de ninguna clase.",
     "$235,000, al aplicar la tasa del 53% al valor presunto y después restar el impuesto acreditable que fue comprobado.",
     "$250,000, al aplicar la tasa del 50% al valor presunto.",
     "$249,100, al disminuir el impuesto acreditable del valor presunto antes de aplicar la tasa."],
  a:1, why:"Al valor presunto se aplica la tasa y el resultado se reduce con las cantidades acreditables que se comprueben: 500,000 × 53% = 265,000 − 30,000 = $235,000. El RLIEPS exige que lo acreditable corresponda a los meses presuntos y cumpla requisitos.",
  hint:"Primero la tasa, después la resta." },

{ t:"fac", art:"Art. 22 LIEPS",
  q:"En una determinación presuntiva, el valor de las actividades gravadas ya está definido y la tasa aplicable no se discute. El contribuyente solicita reducir el impuesto con una estimación del impuesto acreditable basada únicamente en el margen habitual de su sector, sin comprobar cantidades acreditables. ¿Qué criterio corresponde conforme a la Ley?",
  o:["La reducción procede automáticamente, porque la determinación presuntiva del valor implica también estimar los costos y el acreditamiento.",
     "La reducción no procede con esa estimación, porque la Ley exige reducir sólo con las cantidades acreditables que se comprueben.",
     "La reducción procede si el margen utilizado coincide con el promedio del sector económico del contribuyente.",
     "La reducción procede hasta el monto que resulte de aplicar la tasa a los costos estimados de la actividad."],
  a:1, why:"El art. 22 reduce el resultado sólo con las cantidades acreditables que se comprueben, y el art. 19 RLIEPS pide que la documentación cumpla los requisitos legales.",
  hint:"La palabra clave es \"comprueben\"." },

{ t:"fac", art:"Art. 23 LIEPS",
  q:"En una revisión se detecta que un productor de bebidas omitió registrar en su contabilidad adquisiciones de materia prima realizadas en abril. El contribuyente no aporta prueba sobre el destino de esa materia prima. ¿Qué presume la autoridad?",
  o:["Que la materia prima se perdió durante el proceso productivo.",
     "Salvo prueba en contrario, que se utilizó para elaborar productos gravados, enajenados y cobrados en abril, sin declarar el impuesto.",
     "Que los productos se enajenaron en el mes en que se realiza la revisión.",
     "Nada, porque la omisión en el registro de materia prima sólo da lugar a una multa por infracción a las obligaciones de contabilidad."],
  a:1, why:"Se presume, salvo prueba en contrario, que la materia prima no registrada se usó para productos gravados, enajenados y efectivamente cobrados en el mes de adquisición. Valor: precio promedio de los tres meses anteriores al pago.",
  hint:"El mes de adquisición es la referencia." },

{ t:"fac", art:"Art. 23-B LIEPS",
  q:"La autoridad encuentra botellas de licor sin marbete en una bodega que no forma parte de almacenes generales de depósito ni de recintos fiscales. Las bebidas no son de exportación ni portan etiquetas con datos de un importador extranjero. ¿Qué presume la Ley?",
  o:["Que se trata de producto en proceso que aún no ha sido enajenado, porque las botellas todavía no cuentan con los signos de control que exige la Ley.",
     "Que fueron enajenadas y cobradas o importadas en el mes en que se encuentran, valuadas al precio promedio de venta al público del mes anterior.",
     "Que se trata de muestras sin valor comercial.",
     "Que únicamente se causó el IVA por su enajenación."],
  a:1, why:"Las bebidas sin marbete o precinto fuera de almacenes o recintos se presumen enajenadas y cobradas o importadas en el mes en que se encuentran. Precio: promedio de venta al público del mes anterior. No aplica a bebidas de exportación en tránsito con etiqueta del importador extranjero.",
  hint:"Sin marbete = presunción." },

{ t:"fac", art:"Art. 24, fr. II LIEPS",
  q:"La autoridad determina presuntivamente el precio de enajenación con el método de costo más utilidad bruta. El contribuyente no presentó su declaración del ISR del ejercicio, por lo que no puede obtenerse de ella el porcentaje de utilidad. ¿Qué porcentaje de utilidad bruta se considera?",
  o:["25%, porque es el porcentaje mínimo de utilidad presunta.",
     "50%, porque así lo establece la Ley cuando no existe declaración de la cual obtener el porcentaje.",
     "30%, porque corresponde al promedio de la industria.",
     "100%, porque se presume que todo el costo constituye utilidad."],
  a:1, why:"El porcentaje se obtiene dividiendo utilidad bruta entre costo según la declaración de ISR; a falta de declaración, se entiende que la utilidad bruta es de 50%.",
  hint:"La mitad." },

{ t:"fac", art:"Art. 25 LIEPS",
  q:"Una cervecera reporta mermas equivalentes al 14% de su producción del ejercicio. La autoridad considera que el porcentaje excede del límite legal. No se acreditan causas extraordinarias. ¿Qué puede presumir la autoridad?",
  o:["Nada, porque las mermas son deducibles y no generan impuesto.",
     "Que se enajenaron las mermas que exceden del 12.3%, al precio más alto al que se vende el producto.",
     "Que se enajenó el 14% total de mermas, al precio promedio del ejercicio.",
     "Que todas las mermas son improcedentes y deben gravarse en su totalidad, al no haberse acreditado causas extraordinarias."],
  a:1, why:"Se presume enajenado lo que exceda de: 12.3% en cerveza; 5% bebidas añejadas en barricas cubiertas, 10% descubiertas, 1.5% otros sistemas y 1% por envasamiento. Valor: el precio más alto de venta.",
  hint:"Cerveza: 12.3%." },

{ t:"fac", art:"Art. 25, fr. III LIEPS",
  q:"Un productor de tequila añeja su producto en barricas ubicadas en lugares descubiertos, expuestas a la intemperie. Consulta cuál es el porcentaje de mermas que puede considerar antes de que la autoridad presuma su enajenación. ¿Qué límite establece la Ley?",
  o:["5%, que es el límite general aplicable al añejamiento de bebidas en barricas de madera.",
     "10%, que es el límite para barricas ubicadas en lugares descubiertos.",
     "1.5%, que es el límite para otros sistemas de añejamiento.",
     "12.3%, que es el límite general para bebidas fermentadas."],
  a:1, why:"Barricas en lugares cubiertos 5%; descubiertos 10%; otros sistemas 1.5%; envasamiento 1%.",
  hint:"A la intemperie se evapora más." },

{ t:"fac", art:"Art. 26 LIEPS",
  q:"Un productor de bebidas alcohólicas fue omiso más de tres veces durante el ejercicio en la presentación de las declaraciones a que se refiere el artículo 19. Solicita a la autoridad nuevos signos de control para continuar envasando. ¿Qué puede hacer la autoridad?",
  o:["Cancelar su inscripción en el padrón y en el RFC.",
     "No proporcionarle marbetes o precintos.",
     "Clausurar la planta de manera definitiva.",
     "Duplicar la tasa del impuesto durante el ejercicio."],
  a:1, why:"La autoridad puede no proporcionar marbetes o precintos si: omite más de tres veces declaraciones del art. 19, tiene adeudos fiscales (salvo convenio o impugnación), no comprueba o usa incorrectamente los marbetes, o no hay relación entre volumen y solicitud.",
  hint:"La sanción se relaciona con los signos de control." },

{ t:"fac", art:"Art. 26-A LIEPS",
  q:"Con motivo de una solicitud de marbetes, la autoridad requiere a un contribuyente información y documentación para constatar el uso adecuado de los signos que le proporcionó previamente. ¿Qué plazo tiene para atender el requerimiento y qué ocurre si no lo hace?",
  o:["15 días; se le impone una multa por incumplimiento y se continúa con el trámite de la solicitud.",
     "10 días; se le tiene por desistido de la solicitud de marbetes o precintos.",
     "5 días; se procede a la clausura del establecimiento.",
     "30 días; se inicia una determinación presuntiva."],
  a:1, why:"Se otorga un plazo de 10 días; si no cumple, se le tiene por desistido de la solicitud de marbetes o precintos que hubiera formulado.",
  hint:"Diez días." },

// ---- Participaciones ----
{ t:"par", art:"Art. 27 LIEPS",
  q:"Una entidad federativa adherida al Sistema Nacional de Coordinación Fiscal pretende establecer un impuesto local sobre la producción y distribución de cerveza en su territorio, con el fin de aumentar su recaudación. ¿Es procedente conforme a la LIEPS?",
  o:["Sí, porque las entidades conservan su potestad tributaria sin limitación.",
     "No, porque las entidades adheridas no mantendrán impuestos locales sobre actos gravados con el IEPS, salvo excepciones como los juegos con apuestas.",
     "Sí, siempre que la tasa local no exceda del 3% y se destine a programas de salud relacionados con el consumo de alcohol.",
     "Sólo los municipios pueden establecer ese tipo de impuestos."],
  a:1, why:"Los estados coordinados no mantendrán impuestos locales sobre actos gravados por IEPS, su producción o distribución. No aplica a impuestos locales sobre juegos con apuestas y sorteos (art. 2, fr. II, inc. B).",
  hint:"Coordinación fiscal = no doble tributación local." },

{ t:"par", art:"Art. 28 LIEPS",
  q:"Una entidad federativa no adherida al Sistema Nacional de Coordinación Fiscal recibe participaciones de la recaudación del impuesto sobre cerveza consumida en su territorio. ¿Qué porcentajes corresponden a la entidad consumidora y a sus municipios?",
  o:["2.8% para la entidad, por ser el porcentaje que corresponde a las entidades donde se produce y consume el bien.",
     "36.6% para la entidad donde se consume y 7.9% para sus municipios.",
     "13% para la entidad y 5% para sus municipios.",
     "8% para la entidad y 2% para sus municipios."],
  a:1, why:"Cerveza: 2.8% a entidades productoras, 36.6% a donde se consuma y 7.9% a sus municipios. Gasolina: 8% entidades y 2% municipios. Tabacos: 2% productoras, 13% consumidoras, 5% municipios.",
  hint:"El porcentaje más alto del artículo." },

{ t:"par", art:"Art. 28, último párrafo LIEPS",
  q:"Una entidad federativa no adherida, en la que se cultiva tabaco, pretende gravar con impuestos locales y municipales la producción, acopio y venta de tabaco en rama. ¿Cuál es el límite que establece la Ley?",
  o:["$1.55 por kilogramo, considerando en conjunto los impuestos locales y municipales, y sólo en las entidades donde se cultive.",
     "3% del valor de la venta del tabaco en rama.",
     "$0.85 por kilogramo, únicamente para impuestos estatales.",
     "No puede gravarlo, porque el tabaco se encuentra sujeto al impuesto federal."],
  a:0, why:"Pueden gravar la producción, acopio o venta de tabaco en rama con impuestos locales o municipales que en conjunto no excedan de un peso cincuenta y cinco centavos por kilo; sólo las entidades donde se cultive.",
  hint:"Un peso con cincuenta y cinco." },

// ---- Reglamento ----
{ t:"reg", art:"Art. 3 RLIEPS",
  q:"Un fabricante otorga una bonificación a un cliente por bebidas ya facturadas, respecto de las cuales trasladó el impuesto. La bonificación no se pactó en el comprobante original. Antes de disminuir el impuesto conforme al artículo 6o. de la Ley, ¿qué debe hacer según el Reglamento?",
  o:["Nada adicional, porque basta con registrar la bonificación en su contabilidad.",
     "Restituir el impuesto trasladado y expedir una nota de crédito que lo haga constar expresamente.",
     "Cancelar el comprobante original y expedir uno nuevo por el importe neto, una vez descontada la bonificación otorgada.",
     "Presentar un aviso a la autoridad con 15 días de anticipación."],
  a:1, why:"El RLIEPS exige restituir el IEPS trasladado y expedir nota de crédito que lo haga constar, salvo descuentos pactados en el mismo documento de la operación.",
  hint:"Documento fiscal de ajuste." },

{ t:"reg", art:"Art. 4 RLIEPS",
  q:"Un contribuyente recibe la devolución de mercancía por la que ya pagó el impuesto, pero todavía no reembolsa al cliente la contraprestación correspondiente, ni se ha extinguido la obligación de hacerlo. Pretende disminuir el impuesto en la declaración del mes. ¿Qué criterio corresponde?",
  o:["Puede disminuirlo desde que recibe físicamente la mercancía devuelta, porque en ese momento se revierte la enajenación original para efectos fiscales.",
     "No puede disminuirlo aún, porque procede cuando la contraprestación se restituya efectivamente o se extinga la obligación de hacerlo.",
     "Puede disminuirlo siempre que haya expedido la nota de crédito.",
     "Sólo puede disminuirlo al cierre del ejercicio."],
  a:1, why:"La disminución del art. 6 procede cuando la contraprestación se haya restituido efectivamente al adquirente o se extinga la obligación; en descuentos y bonificaciones, cuando se apliquen efectivamente.",
  hint:"Congruente con el flujo de efectivo." },

{ t:"reg", art:"Art. 5 RLIEPS",
  q:"Al levantar el inventario físico en agosto, un contribuyente detecta un faltante de bebidas que no se origina en caso fortuito, fuerza mayor ni destrucción autorizada. No puede identificar la fecha en que ocurrió. ¿En qué mes se entiende realizada la enajenación conforme al Reglamento?",
  o:["En el mes de la última adquisición de las bebidas faltantes, porque se presume que desde entonces salieron del inventario.",
     "En el mes en que se levanta el inventario, pagando el impuesto en la declaración de ese mes.",
     "Al cierre del ejercicio fiscal.",
     "En el mes en que la autoridad notifique el faltante."],
  a:1, why:"En faltantes de inventario, la enajenación se entiende realizada en el mes en que se levante el inventario y el impuesto se paga en la declaración de ese mes.",
  hint:"El mes del conteo." },

{ t:"reg", art:"Art. 7 RLIEPS",
  q:"Un fabricante entrega materialmente bebidas a su comprador dentro de un recinto fiscalizado ubicado en territorio nacional. Las mercancías no han salido del país ni se ha tramitado su exportación. ¿Dónde se considera realizada la enajenación?",
  o:["En el extranjero, porque los recintos fiscalizados se asimilan a territorio extranjero para efectos de los impuestos al comercio exterior.",
     "En territorio nacional, aun cuando la entrega material se efectúe en recintos fiscales o fiscalizados.",
     "En ningún lugar, hasta que las mercancías salgan del recinto.",
     "Depende del domicilio fiscal del comprador."],
  a:1, why:"El RLIEPS considera realizada la enajenación en territorio nacional aunque la entrega material se efectúe en recintos fiscales o fiscalizados.",
  hint:"El recinto sigue siendo México." },

{ t:"reg", art:"Art. 8 RLIEPS",
  q:"Un bien gravado que fue exportado en definitiva retorna posteriormente al país porque el cliente extranjero lo rechazó. El exportador considera que, al tratarse de un retorno, no causa el impuesto. ¿Qué tratamiento corresponde?",
  o:["Es un retorno exento, porque se trata de mercancía nacional que regresa al país sin haber sido transformada en el extranjero.",
     "Queda comprendido en el artículo 12 de la Ley, es decir, se trata como importación que causa el impuesto.",
     "Se considera mercancía nacional, sin causación del impuesto especial.",
     "Únicamente causa el impuesto al valor agregado."],
  a:1, why:"El retorno al país de bienes exportados en definitiva queda comprendido en el art. 12 de la Ley (importación). La exención del art. 13 es para el retorno de bienes exportados temporalmente.",
  hint:"Definitiva ≠ temporal." },

{ t:"reg", art:"Art. 9 RLIEPS",
  q:"Un importador impugna la resolución de la autoridad aduanera que determinó un impuesto general de importación mayor al que él calculó. Mientras se resuelve la controversia, debe determinar el impuesto especial de la importación. ¿Qué establece el Reglamento sobre la diferencia?",
  o:["No debe pagar el impuesto especial hasta que se resuelva la controversia, porque su base depende del impuesto general de importación impugnado.",
     "La diferencia puede pagarse al resolverse en definitiva, con actualización y recargos, garantizando el interés fiscal.",
     "Debe pagar el doble del impuesto como garantía.",
     "Debe calcular el impuesto con base en el valor de la factura comercial."],
  a:1, why:"Si se impugnan resoluciones aduaneras, la diferencia puede pagarse al resolverse definitivamente la controversia, con actualización y recargos, y debe garantizarse el interés fiscal conforme al CFF.",
  hint:"Garantía + actualización y recargos." },

{ t:"reg", art:"Art. 10 RLIEPS",
  q:"Un importador introduce un bien gravado con el impuesto especial que, por virtud de un tratado comercial, no paga impuesto general de importación. Consulta cómo debe enterar el impuesto especial de la importación. ¿Qué establece el Reglamento?",
  o:["Debe enterarlo en su declaración mensual del día 17.",
     "Debe enterarlo con la misma forma utilizada para el impuesto general de importación, aunque éste no deba pagarse.",
     "Puede enterarlo en cualquier institución bancaria autorizada mediante formato libre, al no existir impuesto general de importación a pagar.",
     "No lo entera, porque no existe impuesto general de importación."],
  a:1, why:"El IEPS en importaciones se entera con la misma forma usada para el IGI, aun cuando no deba pagarse este último (la Ley remite a declaración en la aduana).",
  hint:"El pedimento." },

{ t:"reg", art:"Art. 11 RLIEPS",
  q:"Un comisionista vende cerveza por cuenta de un comitente y cobra por ello una comisión, además de recibir reembolsos de gastos efectuados por cuenta de éste. Para efectos del Reglamento, ¿quién considera a su cargo el impuesto de la venta y sobre qué base?",
  o:["El comisionista, sobre el precio total de la venta, por ser quien realiza materialmente la operación con el adquirente.",
     "El comitente, sin descontar la comisión ni los reembolsos; el comisionista sólo sobre su comisión.",
     "Ambos, por partes iguales, sobre el precio total de la venta, porque los dos intervienen en la enajenación del bien.",
     "Ninguno, porque se trata de una operación de intermediación."],
  a:1, why:"El comitente considera a su cargo el IEPS de los actos del comisionista sin descontar comisión ni reembolsos. El comisionista considera a su cargo el impuesto sobre su comisión.",
  hint:"Cada uno sobre lo suyo." },

{ t:"reg", art:"Art. 12 RLIEPS",
  q:"Un productor de alcohol lleva, además de la contabilidad del CFF, registros del volumen y valor de sus materias primas, producción y mermas. Consulta en qué unidad debe expresar la graduación del alcohol en dichos registros. ¿Qué establece el Reglamento?",
  o:["En grados Brix a 20 °C.",
     "En grados Gay-Lussac, medidos a la temperatura de 15 °C.",
     "En porcentaje de volumen a 25 °C.",
     "En grados Celsius de destilación."],
  a:1, why:"Además de la contabilidad del CFF, los productores registran volumen y valor de materias primas, producción y mermas; el alcohol se registra en grados Gay-Lussac a 15 °C.",
  hint:"Mismo estándar de las definiciones del art. 3." },

{ t:"reg", art:"Art. 14 RLIEPS",
  q:"Un fabricante trasladará el impuesto en forma expresa y por separado a un adquirente que es contribuyente y que así lo solicitó. Antes de expedir el comprobante, debe cumplir con un requisito de verificación previsto en el Reglamento. ¿Cuál es?",
  o:["Verificar que el adquirente esté al corriente en sus obligaciones con el IMSS.",
     "Verificar que el nombre o razón social del receptor coincida con su constancia de inscripción en el RFC y anotar el número de ésta.",
     "Verificar que el adquirente cuente con firma electrónica vigente.",
     "Verificar que el adquirente pague la contraprestación de contado, porque el traslado expreso sólo procede en operaciones efectivamente cobradas."],
  a:1, why:"El RLIEPS pide verificar que el nombre o razón social del receptor coincida con su constancia de inscripción en el RFC y anotar el número de dicha constancia en el comprobante.",
  hint:"Se trata de identificar al receptor." },

{ t:"reg", art:"Arts. 15 y 16 RLIEPS",
  q:"Un exportador enajena al extranjero bebidas alcohólicas envasadas, mientras que otro contribuyente transporta bebidas alcohólicas a granel entre sus plantas en territorio nacional. ¿Qué obligación corresponde a cada uno, respectivamente?",
  o:["Adherir marbetes en ambos casos, porque se trata de bebidas alcohólicas.",
     "Adherir etiquetas con datos del importador extranjero; y adherir precintos en todas las entradas y salidas del recipiente.",
     "Imprimir un código QR en cada envase y colocar un sello aduanal en el recipiente a granel durante su traslado.",
     "Ninguna en ambos casos, porque no existe enajenación al público en general ni consumo en territorio nacional."],
  a:1, why:"El exportador adhiere etiquetas con datos del importador extranjero (o de tiendas libres de impuestos, si vende a ellas). Quien transporta a granel adhiere precintos en todas las entradas y salidas por donde se pueda cargar o descargar.",
  hint:"Exportación → etiqueta; granel → precinto." },

{ t:"reg", art:"Art. 17 RLIEPS",
  q:"Un bar considera impráctico destruir cada envase vacío inmediatamente después de agotar su contenido, debido al volumen de botellas que maneja diariamente. ¿Qué opción le otorga el Reglamento?",
  o:["Destruirlos una vez al mes, levantando un acta circunstanciada ante fedatario público con la relación de folios de los marbetes.",
     "Destruirlos una vez por semana, el mismo día, raspando etiquetas, contraetiquetas y marbetes y registrando sus folios.",
     "Venderlos a un centro de reciclaje autorizado.",
     "Entregarlos a la autoridad para su destrucción."],
  a:1, why:"Se puede optar por destruir los envases vacíos una vez por semana, el mismo día; al cierre del día se raspan etiquetas y marbetes, registrando folios, y se conserva la información.",
  hint:"Periodicidad semanal." },

{ t:"reg", art:"Art. 18 RLIEPS",
  q:"Para efectos de la distribución de participaciones a las entidades federativas, los productores deben llevar ciertos registros sobre sus operaciones. Un fabricante distribuye sus productos en varios estados del país. ¿Cómo debe registrar sus operaciones?",
  o:["Por sucursal bancaria en la que recibe los pagos.",
     "Por cada entidad federativa en la que se distribuyan los bienes, considerando el valor de las enajenaciones o importaciones gravadas realizadas.",
     "Únicamente en el domicilio fiscal del contribuyente, porque las declaraciones de pago se presentan ante las oficinas de ese domicilio.",
     "Por código postal del domicilio de cada cliente."],
  a:1, why:"Los productores registran por entidad federativa de distribución el valor de enajenaciones o importaciones gravadas; en cerveza, refrescos y tabacos labrados también la producción por entidad.",
  hint:"Relación con el art. 19, fr. VI de la Ley." },

{ t:"reg", art:"Art. 2 RLIEPS",
  q:"Un contribuyente presenta una declaración complementaria del impuesto, de la cual resulta un saldo a favor que no existía en la declaración original. Consulta qué puede hacer con ese saldo. ¿Qué permite el Reglamento?",
  o:["Únicamente solicitar su devolución.",
     "Compensarlo conforme al artículo 5o. de la Ley o aplicarlo en la declaración de pago siguiente a la fecha en que se presente la declaración complementaria.",
     "Acreditarlo contra el impuesto al valor agregado.",
     "Nada, porque los saldos a favor que derivan de declaraciones complementarias se pierden si no se solicitó su devolución en la original."],
  a:1, why:"Si una complementaria genera saldo a favor o lo aumenta, puede compensarse conforme al art. 5 de la Ley o aplicarse en la declaración de pago siguiente a la fecha en que se presente la complementaria.",
  hint:"La complementaria no impide usar el saldo." }
);
